<div class="page-heading"><h1>Evaluasi & Hasil Belajar</h1><p>Kerjakan evaluasi sesuai waktu yang ditetapkan. Hasil praktik diisi oleh instruktur.</p></div>
<?php $assessmentId=(int)query('assessment');if($assessmentId):$assessment=assessmentForUser($assessmentId,$uid);$attempt=one('SELECT * FROM assessment_attempts WHERE assessment_id=? AND user_id=?',[$assessmentId,$uid]); ?>
<section class="panel"><h2><?= e($assessment['title']) ?></h2><p class="lesson-body"><?= e($assessment['instructions']) ?></p>
<?php if($attempt&&!$attempt['submitted_at']&&$assessment['kind']!=='practical'): ?>
<p class="notice info" data-exam-expiry="<?= e(date(DATE_ATOM,strtotime($attempt['expires_at']))) ?>">Batas waktu: <?= e($attempt['expires_at']) ?> WIB</p><p class="muted">Jawaban yang dikirim setelah waktu berakhir tidak dinilai. Kirim sebelum waktu habis.</p><form class="portal-form" method="post" data-busy-form><?= actionFields('submit_assessment',$assessmentId) ?>
<?php $questions=rows('SELECT id,question,options_json FROM assessment_questions WHERE assessment_id=? ORDER BY sort_order,id',[$assessmentId]);foreach($questions as $index=>$question): ?><fieldset class="portal-question"><legend><?= ($index+1).'. '.e($question['question']) ?></legend><?php foreach(json_decode($question['options_json'],true) as $key=>$option): ?><label><input type="radio" name="answers[<?= (int)$question['id'] ?>]" value="<?= (int)$key ?>"><?= e($option) ?></label><?php endforeach; ?></fieldset><?php endforeach; ?><button type="submit" class="btn">Kirim jawaban final</button></form>
<?php elseif($attempt&&$attempt['submitted_at']): ?><p class="notice">Nilai: <?= e($attempt['score']) ?> · <?= $attempt['passed']?'Lulus':'Belum lulus' ?></p><p class="lesson-body"><?= e($attempt['feedback']) ?></p><?php if($assessment['reveal_answers']&&strtotime($assessment['closes_at'])<time()):$answers=rows('SELECT q.question,q.options_json,q.correct_option,a.selected_option FROM assessment_questions q JOIN assessment_answers a ON a.question_id=q.id WHERE a.attempt_id=? ORDER BY q.sort_order,q.id',[$attempt['id']]);foreach($answers as $answer):$options=json_decode($answer['options_json'],true); ?><div class="panel"><h3><?= e($answer['question']) ?></h3><p class="muted">Jawaban Anda: <?= e($options[$answer['selected_option']]??'Tidak dijawab') ?></p><p class="muted">Jawaban benar: <?= e($options[$answer['correct_option']]??'') ?></p></div><?php endforeach;else: ?><p class="muted">Pembahasan belum dibuka oleh instruktur.</p><?php endif; ?>
<?php else: ?><p class="muted">Mulai evaluasi melalui daftar di bawah sesuai jadwal yang tersedia.</p><?php endif; ?></section>
<?php endif; ?>
<?php $assessments=rows("SELECT a.*,at.id attempt_id,at.submitted_at,at.score,at.passed,p.title program_title FROM assessments a JOIN registrations r ON r.batch_id=a.batch_id JOIN enrollments en ON en.registration_id=r.id JOIN training_batches b ON b.id=a.batch_id JOIN training_programs p ON p.slug=b.program_slug LEFT JOIN assessment_attempts at ON at.assessment_id=a.id AND at.user_id=r.user_id WHERE r.user_id=? AND r.status='approved' AND en.status IN ('active','completed') AND a.is_published=1 ORDER BY a.opens_at DESC",[$uid]);if(!$assessments)emptyState('Belum ada evaluasi','Evaluasi dan hasil penilaian praktik akan tersedia setelah diterbitkan instruktur.','portal.php?view=learning','Kembali belajar'); ?>
<div class="portal-grid" style="margin-top:24px"><?php foreach($assessments as $item): ?><article class="panel"><span class="badge"><?= e(['quiz'=>'Kuis','exam'=>'Ujian','practical'=>'Praktik'][$item['kind']]) ?></span><h2 style="margin-top:16px"><?= e($item['title']) ?></h2><p class="muted"><?= e($item['program_title']) ?></p><p class="muted"><?= e($item['opens_at'].' — '.$item['closes_at']) ?> WIB</p><p class="muted">Durasi <?= (int)$item['duration_minutes'] ?> menit · Nilai lulus <?= e($item['pass_score']) ?></p><div class="actions"><?php if($item['submitted_at']): ?><a class="btn secondary" href="portal.php?view=assessments&amp;assessment=<?= (int)$item['id'] ?>">Nilai <?= e($item['score']) ?> · <?= $item['passed']?'Lulus':'Belum lulus' ?></a><?php elseif($item['attempt_id']): ?><a class="btn" href="portal.php?view=assessments&amp;assessment=<?= (int)$item['id'] ?>">Lanjutkan evaluasi</a><?php elseif($item['kind']!=='practical'&&strtotime($item['opens_at'])<=time()&&strtotime($item['closes_at'])>time()): ?><form method="post" data-busy-form><?= actionFields('start_assessment',(int)$item['id']) ?><button type="submit" class="btn">Mulai evaluasi</button></form><?php else: ?><span class="muted"><?= $item['kind']==='practical'?'Menunggu hasil instruktur':'Di luar waktu evaluasi' ?></span><?php endif; ?></div></article><?php endforeach; ?></div>
